// Mural home score (ADR 0246, bipe-chat/bipe#1044): the reference rule. The formula is in registries/home-score.json.
// Pure: it reads only its arguments. The generated Swift and Kotlin (gen-home-score.mjs) and the web client run the same steps.

/** A score part in integer units of 1/10000. */
export const homeUnits = (x) => Math.floor(x * 10000 + 0.5);

const nonNegative = (n) => Math.max(n ?? 0, 0);
const isDirect = (chat) => chat.kind !== "group";

function modelUnits(chat, unread, policy) {
  if ((chat.kind === "company" && !chat.hasSeal) || chat.official || chat.trustWarning) return 0;
  const model = policy.model;
  let units = 0;
  const attention = chat.modelAttention;
  if (typeof attention === "string" && Object.hasOwn(model.attention, attention) && (attention !== "none" || unread > 0)) {
    units += homeUnits(model.attention[attention]);
  }
  if (chat.modelDue === true) units += homeUnits(model.due);
  return Math.min(units, homeUnits(model.maxWeight));
}

function unanswered(chat, unread, minutes, policy) {
  return isDirect(chat) && unread === 0 && chat.lastFromOther === true && minutes !== null && minutes < policy.unansweredMaxMinutes;
}

/** { scorePercent, score, reason } of one chat. reason: "mention", "unanswered" or null. */
export function homeScore(chat, policy) {
  const unread = nonNegative(chat.unreadCount);
  const minutes = chat.minutesSinceActivity == null ? null : Math.max(chat.minutesSinceActivity, 0);
  const w = policy.weights;
  let sum = 0;
  if (chat.mentioned) sum += homeUnits(w.mention);
  if (unread > 0) {
    if (isDirect(chat)) sum += homeUnits(chat.kind === "company" && !chat.hasSeal ? w.unreadCompanyNoSeal : w.unreadDirect);
    else sum += Math.min(homeUnits(policy.unreadGroup.max), homeUnits(policy.unreadGroup.min + policy.unreadGroup.logScale * Math.log10(1 + unread)));
  }
  const isUnanswered = unanswered(chat, unread, minutes, policy);
  if (isUnanswered) sum += homeUnits(w.unansweredDirect);
  if (chat.favourite) sum += homeUnits(w.favourite);
  sum += Math.min(homeUnits(policy.tie.max), homeUnits(policy.tie.logScale * Math.log2(1 + nonNegative(chat.messagesPerWeek))));
  if (minutes !== null) sum += homeUnits(policy.recency.max * Math.exp(-minutes / policy.recency.decayMinutes));
  sum += modelUnits(chat, unread, policy);
  if (chat.muted && !chat.mentioned) sum = Math.floor(sum * policy.mutedFactor + 0.5);
  if (chat.official) sum = Math.min(sum, homeUnits(policy.officialCap));
  sum = Math.min(Math.max(sum, 0), 10000);
  const scorePercent = Math.floor((sum + 50) / 100);
  return { scorePercent, score: scorePercent / 100, reason: chat.mentioned ? "mention" : isUnanswered ? "unanswered" : null };
}

/** The tiles in screen order: { id, scorePercent, score, tier, reason }. tier null: no tile, the chat is only in the plain list. */
export function homePlan(chats, policy) {
  const minutesKey = (chat) => (chat.minutesSinceActivity == null ? Infinity : Math.max(chat.minutesSinceActivity, 0));
  const ordered = chats.map((chat) => ({ chat, scored: homeScore(chat, policy) })).sort((a, b) => {
    if (a.scored.scorePercent !== b.scored.scorePercent) return b.scored.scorePercent - a.scored.scorePercent;
    const am = minutesKey(a.chat);
    const bm = minutesKey(b.chat);
    if (am !== bm) return am - bm;
    return a.chat.id < b.chat.id ? -1 : a.chat.id > b.chat.id ? 1 : 0;
  });
  const counts = new Map();
  return ordered.map(({ chat, scored }) => {
    const rule = policy.tiers.find((t) => scored.scorePercent >= Math.floor(t.minScore * 100 + 0.5) && (t.maxChats === null || (counts.get(t.tier) ?? 0) < t.maxChats));
    if (rule) counts.set(rule.tier, (counts.get(rule.tier) ?? 0) + 1);
    return { id: chat.id, ...scored, tier: rule ? rule.tier : null };
  });
}
